const upsertCodeMember = `-- name: UpsertCodeMember :one
INSERT INTO code_members (code_id, display_name, email, is_anonymous)
VALUES ($1, $2, $3, $4)
ON CONFLICT (code_id, display_name) DO UPDATE SET last_seen_at = now()
RETURNING id, code_id, display_name, email, is_anonymous, last_seen_at
`

type UpsertCodeMemberParams struct {
	CodeID      pgtype.UUID
	DisplayName string
	Email       *string
	IsAnonymous bool
}

// The actual persist step. Whether a seat is available is decided by the caller within the same
// transaction, after acquiring the row lock -- so this query no longer carries a gate of its own
// (carrying one would be useless anyway; see the LockCodeForMemberInsert comment).
func (q *Queries) UpsertCodeMember(ctx context.Context, arg UpsertCodeMemberParams) (CodeMember, error) {
	row := q.db.QueryRow(ctx, upsertCodeMember,
		arg.CodeID,
		arg.DisplayName,
		arg.Email,
		arg.IsAnonymous,
	)
	var i CodeMember
	err := row.Scan(
		&i.ID,
		&i.CodeID,
		&i.DisplayName,
		&i.Email,
		&i.IsAnonymous,
		&i.LastSeenAt,
	)
	return i, err
}
